'''E24 — corrected M-family replay-router.

Behavior-derived from the user's 2026-09-18 public Kaggriculture replay corpus.

Family identity:
- 4H / 2C3S opening
- M6-class melon opening
- second land around step 150
- third land around step 220
- shop-conditioned M-family route selection

The route library stores only public replay actions and unit positions.
No competitor source code is embedded.

This is a corrected local experimental candidate.
'''

from __future__ import annotations

import base64
import copy
import json
import zlib
from collections import Counter

_ROUTE_DATA_B64 = ""
_ROUTES = json.loads(zlib.decompress(base64.b64decode(_ROUTE_DATA_B64)))

_HANDS_BY_DAY = [
    4,4,6,6,6,6,8,9,9,10,
    11,11,11,11,11,11,11,11,11,11,
    11,11,11,11,11,11,11,11,10,10,
]

_SHOP_PRODUCTS = {
    "BAKERY": ("EGG", "WHEAT"),
    "PIZZA_SHOP": ("MILK", "TOMATO", "WHEAT"),
    "BRUNCH_SPOT": ("EGG", "WHEAT", "STRAWBERRY"),
    "YARN_STORE": ("WOOL",),
    "ICE_CREAM_SHOP": ("STRAWBERRY", "MILK", "WHEAT"),
    "PET_CAFE": ("CARROT",),
    "SMOOTHIE_SHOP": ("STRAWBERRY", "MILK"),
    "FARMERS_MARKET": ("WHEAT", "CARROT", "TOMATO", "STRAWBERRY"),
}

_SHED_TILES = ((4,4),(5,4),(4,5),(5,5))
_MOVE = {"NORTH","SOUTH","EAST","WEST"}
_STATE = {}

TELEMETRY = {
    "calls": 0,
    "route_switches": 0,
    "repaired_commands": 0,
    "exact_route_matches": 0,
    "fallback_route_matches": 0,
}


def _dist(a, b):
    return abs(int(a[0]) - int(b[0])) + abs(int(a[1]) - int(b[1]))


def _nearest_shed(pos):
    return min(_SHED_TILES, key=lambda x: _dist(pos, x))


def _step_toward(pos, target):
    x, y = int(pos[0]), int(pos[1])
    tx, ty = int(target[0]), int(target[1])
    dx, dy = tx - x, ty - y
    if dx == 0 and dy == 0:
        return ["PASS"]
    if abs(dx) >= abs(dy):
        return ["EAST" if dx > 0 else "WEST"]
    return ["SOUTH" if dy > 0 else "NORTH"]


def _demand(shops):
    c = Counter()
    for shop in shops:
        c.update(_SHOP_PRODUCTS.get(shop, ()))
    return c


def _route_prefix(route, k):
    if k <= 0:
        return ()
    return tuple(route.get(f"first{k}", ()))


def _current_positions(obs):
    player = int(obs["player"])
    farm = obs["farms"][player]
    return [farm.get("farmer")] + list(farm.get("hands") or [])


def _position_penalty(route, step, obs):
    try:
        donor = route["positions"][step]
        current = _current_positions(obs)
        if not donor or not current:
            return 999
        p = _dist(current[0], donor[0])
        unused = list(range(1, len(donor)))
        for cp in current[1:]:
            if not unused:
                p += 8
                continue
            j = min(unused, key=lambda x: _dist(cp, donor[x]))
            p += _dist(cp, donor[j])
            unused.remove(j)
        p += 2 * abs((len(current)-1) - (len(donor)-1))
        return p
    except Exception:
        return 999


def _select_route(obs, step):
    shops = tuple((obs.get("town") or {}).get("unlocked_shops") or [])
    k = min(4, len(shops))

    if k == 0:
        return 0, True

    exact = []
    for i, route in enumerate(_ROUTES):
        if _route_prefix(route, k) == shops[:k]:
            exact.append(i)

    if exact:
        best = min(exact, key=lambda i: _position_penalty(_ROUTES[i], step, obs))
        return best, True

    want = _demand(shops[:k])
    products = ("MILK","WOOL","CARROT","TOMATO","STRAWBERRY","WHEAT","EGG")

    def key(i):
        route = _ROUTES[i]
        have = _demand(_route_prefix(route, k))
        demand_gap = sum(abs(want.get(p,0) - have.get(p,0)) for p in products)
        sequence_gap = sum(
            1 for a,b in zip(shops[:k], _route_prefix(route,k))
            if a != b
        )
        pos = _position_penalty(route, step, obs)
        donor_penalty = 0 if route.get("team") == "Majkel1337" else 1
        return (demand_gap, sequence_gap, pos, donor_penalty)

    return min(range(len(_ROUTES)), key=key), False


def _player_state(obs):
    player = int(obs.get("player", 0))
    step = int(obs.get("step", 0))
    if step == 0 or player not in _STATE:
        _STATE[player] = {"route": 0, "shops_seen": -1}
    return _STATE[player]


def _route_for_turn(obs):
    step = int(obs.get("step", 0))
    state = _player_state(obs)
    shops = tuple((obs.get("town") or {}).get("unlocked_shops") or [])
    k = min(4, len(shops))

    if state["shops_seen"] != k:
        idx, exact = _select_route(obs, step)
        if idx != state["route"]:
            TELEMETRY["route_switches"] += 1
        state["route"] = idx
        state["shops_seen"] = k
        TELEMETRY["exact_route_matches" if exact else "fallback_route_matches"] += 1

    return _ROUTES[state["route"]]


def _map_hand_commands(obs, route, step, action):
    player = int(obs["player"])
    farm = obs["farms"][player]
    current_hands = list(farm.get("hands") or [])
    donor_pos = route["positions"][step]
    donor_hands = donor_pos[1:] if donor_pos else []
    donor_cmds = list(action.get("hands") or [])

    if not current_hands:
        return []

    unused = list(range(min(len(donor_hands), len(donor_cmds))))
    mapped = []

    for cp in current_hands:
        if not unused:
            mapped.append(["PASS"])
            continue
        j = min(unused, key=lambda x: _dist(cp, donor_hands[x]))
        unused.remove(j)
        mapped.append(copy.deepcopy(donor_cmds[j]))

    return mapped


def _repair_market(obs, market):
    player = int(obs["player"])
    farm = obs["farms"][player]
    private = obs.get("private") or {}
    shed = Counter(private.get("shed") or {})
    unlocked = list(farm.get("unlocked_quadrants") or [])

    step = int(obs.get("step", 0))
    day, hour = divmod(step, 24)

    out = []

    # Preserve donor timing for HIRE / BUY_LAND / purchases.
    # In this family the opening is cash-flow sensitive; moving HIRE or land
    # orders earlier changes whether the animal/seed purchases behind them clear.
    sold = Counter()
    for order in market or []:
        if not isinstance(order, (list, tuple)) or not order:
            continue
        op = str(order[0])

        o = list(order)
        if op == "SELL" and len(o) >= 2:
            item = str(o[1])
            try:
                qty = int(o[2]) if len(o) > 2 else 1
            except Exception:
                qty = 1
            qty = max(0, min(qty, int(shed.get(item, 0) - sold[item])))
            if qty <= 0:
                continue
            if len(o) > 2:
                o[2] = qty
            else:
                o.append(qty)
            sold[item] += qty

        out.append(o)

    return out[:10]


def _unit_positions_and_inventories(obs):
    player = int(obs["player"])
    farm = obs["farms"][player]
    positions = [farm.get("farmer")] + list(farm.get("hands") or [])
    invs = list((obs.get("private") or {}).get("inventories") or [])
    while len(invs) < len(positions):
        invs.append({})
    return positions, invs


def _repair_commands(obs, farmer_cmd, hand_cmds, market):
    player = int(obs["player"])
    farm = obs["farms"][player]
    tiles = farm.get("tiles") or []
    private = obs.get("private") or {}

    positions, invs = _unit_positions_and_inventories(obs)

    seed_budget = Counter(private.get("seeds") or {})
    shed_budget = Counter(private.get("shed") or {})

    for o in market:
        if not o:
            continue
        op = str(o[0])
        item = str(o[1]) if len(o) > 1 else ""
        try:
            qty = int(o[2]) if len(o) > 2 else 1
        except Exception:
            qty = 1
        if op == "BUY_SEED":
            seed_budget[item] += qty
        elif op in ("BUY_PRODUCT", "BUY_ANIMAL"):
            shed_budget[item] += qty
        elif op == "SELL":
            shed_budget[item] = max(0, shed_budget[item] - qty)

    cmds = [farmer_cmd] + list(hand_cmds)

    def tile_at(pos):
        try:
            x, y = int(pos[0]), int(pos[1])
            return tiles[y][x]
        except Exception:
            return None

    def repair(i, cmd):
        if not isinstance(cmd, (list, tuple)) or not cmd:
            return ["PASS"]

        cmd = list(cmd)
        op = str(cmd[0])
        pos = positions[i] if i < len(positions) else None
        inv = Counter(invs[i] if i < len(invs) else {})
        tile = tile_at(pos) if pos is not None else None

        if op in _MOVE or op == "PASS":
            return cmd

        if op in ("PICKUP", "DROP"):
            if pos is None:
                return ["PASS"]
            if tuple(pos) not in _SHED_TILES:
                TELEMETRY["repaired_commands"] += 1
                return _step_toward(pos, _nearest_shed(pos))

            if len(cmd) < 2:
                return ["PASS"]
            item = str(cmd[1])
            try:
                qty = int(cmd[2]) if len(cmd) > 2 else 1
            except Exception:
                qty = 1

            if op == "PICKUP":
                qty = min(qty, int(shed_budget.get(item, 0)))
                if qty <= 0:
                    return ["PASS"]
                shed_budget[item] -= qty
            else:
                qty = min(qty, int(inv.get(item, 0)))
                if qty <= 0:
                    return ["PASS"]

            return [op, item, qty]

        if op == "PLANT":
            if len(cmd) < 2:
                return ["PASS"]
            crop = str(cmd[1])
            if isinstance(tile, dict) and tile.get("kind") == "WEED":
                TELEMETRY["repaired_commands"] += 1
                return ["DIG"]
            if tile is not None or seed_budget.get(crop, 0) <= 0:
                TELEMETRY["repaired_commands"] += 1
                return ["PASS"]
            seed_budget[crop] -= 1
            return ["PLANT", crop]

        if op.startswith("BUILD_"):
            if isinstance(tile, dict) and tile.get("kind") == "WEED":
                TELEMETRY["repaired_commands"] += 1
                return ["DIG"]
            if tile is not None:
                TELEMETRY["repaired_commands"] += 1
                return ["PASS"]
            return cmd

        if op == "PLACE":
            if len(cmd) < 2:
                return ["PASS"]
            animal = str(cmd[1])
            if inv.get(animal, 0) <= 0:
                TELEMETRY["repaired_commands"] += 1
                return ["PASS"]
            if not isinstance(tile, dict) or tile.get("kind") not in ("PASTURE","COOP") or tile.get("animal"):
                TELEMETRY["repaired_commands"] += 1
                return ["PASS"]
            return cmd

        if op == "WATER":
            if not isinstance(tile, dict) or tile.get("kind") != "PLANT" or tile.get("watered_today"):
                return ["PASS"]
            return cmd

        if op == "FEED":
            if not isinstance(tile, dict) or not tile.get("animal") or tile.get("fed_today"):
                return ["PASS"]
            if inv.get("WHEAT", 0) <= 0:
                return ["PASS"]
            return cmd

        if op == "CARE":
            if not isinstance(tile, dict) or not tile.get("animal") or tile.get("cared_today"):
                return ["PASS"]
            return cmd

        if op == "COLLECT_FERTILIZER":
            if not isinstance(tile, dict) or not tile.get("fertilizer_available"):
                return ["PASS"]
            return cmd

        if op == "HARVEST":
            if not isinstance(tile, dict) or int(tile.get("yield_units", 0) or 0) <= 0:
                return ["PASS"]
            return cmd

        if op == "FERTILIZE":
            if not isinstance(tile, dict) or tile.get("kind") != "PLANT":
                return ["PASS"]
            if inv.get("FERTILIZER", 0) <= 0:
                return ["PASS"]
            return cmd

        if op == "DIG":
            if not isinstance(tile, dict) or tile.get("kind") != "WEED":
                return ["PASS"]
            return cmd

        return cmd

    fixed = [repair(i, c) for i, c in enumerate(cmds)]
    hands_n = len(farm.get("hands") or [])
    return fixed[0], fixed[1:1+hands_n]


def agent(observation, configuration=None):
    TELEMETRY["calls"] += 1
    step = int(observation.get("step", 0))

    if step < 0 or step >= 720:
        player = int(observation.get("player", 0))
        farms = observation.get("farms") or [{}]
        farm = farms[player] if player < len(farms) else {}
        hands = len(farm.get("hands") or [])
        return {"farmer":["PASS"], "hands":[["PASS"]]*hands, "market":[]}

    route = _route_for_turn(observation)
    # Kaggle replay semantics: steps[t+1]["action"] is the action that
    # produced state t+1 from state t. Therefore at live step t we must use
    # replay action t+1, while route["positions"][t] is the matching start state.
    if step >= 719:
        raw = {"farmer": ["PASS"], "hands": [], "market": []}
    else:
        raw = copy.deepcopy(route["actions"][step + 1])

    market = _repair_market(observation, raw.get("market") or [])
    hand_cmds = _map_hand_commands(observation, route, step, raw)
    farmer_cmd = copy.deepcopy(raw.get("farmer") or ["PASS"])

    farmer_cmd, hand_cmds = _repair_commands(
        observation,
        farmer_cmd,
        hand_cmds,
        market,
    )

    return {
        "farmer": farmer_cmd,
        "hands": hand_cmds,
        "market": market,
    }


melon_maxxer = agent
